#!/usr/bin/env bash
# Release phase 1, step 1a: derive and PROVE pgrx upgrade scripts, so the
# Release PR carries them the same way it carries the Cargo.toml bump and
# the changelog. Org canon — see docs/release.md (#132).
#
# The upgrade script is a build product, never authored. Both endpoints
# are fully known to the machinery: the previous schema ships inside the
# previous release's own signed tarball, and the candidate schema is
# generated by pgrx from the code being released. Asking a human to write
# or name this file is asking a human to author derived state — the same
# category error as hand-editing CHANGELOG.md — and it is what burned
# v0.16.0 and v0.16.2 in the lab. This is the pattern the largest
# publishers ship on (PostGIS and TimescaleDB both generate their upgrade
# scripts from the canonical schema at build time); pgrx itself declines
# to solve it, so the generation layer is ours.
#
# Derivation alone is not trusted: the script is proven before it is
# committed. A live Postgres installs the PREVIOUS release's real
# tarball, CREATE EXTENSION at the old version, overlays the candidate
# package plus the derived script, ALTER EXTENSION UPDATE — and the
# upgraded catalog must match a fresh install of the candidate EXACTLY,
# compared through pg_depend (pg_dump cannot see extension members; it
# dumps CREATE EXTENSION and nothing else). Anything the generator cannot
# soundly derive therefore fails THIS step — a red Release PR, before any
# tag exists — never the publish. The publish-time guard stays as the
# backstop for a tag minted around this path.
#
# Data migrations are the one thing no schema mechanism can derive. They
# go in an optional, version-free sql/next-data.sql beside the crate's
# other SQL; it is folded into the derived script (and removed by the
# release commit), and the round-trip proof applies to it like everything
# else.
#
# Expects the working tree AFTER prepare-release.sh: manifests already
# carry VERSION, so the candidate build names its schema correctly.
#
# Env in:  VERSION (bumped version), PREV_MANIFEST (pre-bump manifest
#          version, cross-checked against the published release),
#          GH_TOKEN, GITHUB_REPOSITORY.
# Writes GITHUB_OUTPUT key `files`: paths to add to the release commit.
set -euo pipefail
: "${ORG_PYTHON:?unset — the belt Python (CI: the canon action; local: the belt [env])}"

: "${VERSION:?VERSION must be set (the bumped version, no leading v)}"
: "${PREV_MANIFEST:=}"
: "${GH_TOKEN:?GH_TOKEN must be set}"
: "${GITHUB_REPOSITORY:?}"

canon="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
# The canon's writer of findings (#1934), which brings its one writer of
# workflow commands (#1660); the containers below read the copies each
# build places in its /work, and name this script as their task.
# shellcheck source=mise/findings.sh
. "${canon}/mise/findings.sh"
: "${MISE_TASK_NAME:=generate-pgrx-upgrade.sh}"

emit() {
  if [[ -n ${GITHUB_OUTPUT:-} ]]; then
    echo "$1" >> "${GITHUB_OUTPUT}"
  fi
}

# Applicability, detected never configured: a pgrx extension crate is the
# directory holding a checked-in <ext>.control file. No control files, no
# extension crates, nothing to derive — skip clean, per belt convention.
controls=()
tracked_controls=$(git ls-files '*.control')
while IFS= read -r tracked_control; do
  [[ -n ${tracked_control} ]] && controls+=("${tracked_control}")
done <<< "${tracked_controls}"
if ((${#controls[@]} == 0)); then
  echo "no extension control files tracked; pgrx upgrade derivation not applicable"
  emit "files="
  exit 0
fi

# What consumers actually run is recorded by the extension itself, not by
# the forge (#762). Every published version is the target of an upgrade
# script — `<ext>--<from>--<to>.sql` — so the highest `to` in that graph
# IS the latest version a database can be sitting on. That is the same
# source the repo-side upgrade-path lint reads, so the two agree by
# construction rather than by coincidence.
#
# This used to ask `gh release view` for the latest release and require
# its tag to look like `v<version>`. That is true of a repo which has
# always released under the canon and false of an imported one: edtf
# published eleven extension versions as `edtf-postgres-v1.2.3` and
# friends before its import, so the tag test read "first publish" and
# derived nothing, while the lint correctly demanded a path from 1.2.3
# (#669). A tag scheme is a fact about a repository's past; an upgrade
# graph is a fact about installations, and installations are what an
# upgrade path is for.
#
# An EMPTY graph is the only thing that means first publish.
#
# The graph yields CANDIDATES, newest first, not a single answer (#816).
# Its head is the newest version someone meant to publish, which is not
# the newest version anyone can install. A burned release leaves its
# upgrade script in the tree — deliberately, as the burn record — while
# no release carries its tarballs. edtf v1.3.0 was tagged, failed to
# publish, and left `--1.2.3--1.3.0.sql` behind; the derivation asked
# about 1.3.0 alone, found nothing, and called an extension with eleven
# published versions a first publish. Installability is a fact about
# release assets, so it is settled per extension, in the loop below.
predecessor_helper=(-I "${canon}/belt" previous-release)
graph_targets=$("${ORG_PYTHON}" "${predecessor_helper[@]}" graph "${controls[@]}")
graph_head=$(head -n 1 <<< "${graph_targets}")
if [[ -z ${graph_head} ]]; then
  echo "no upgrade graph; first publish of this extension needs no upgrade path"
  emit "files="
  exit 0
fi
# WHAT THE FORGE ANSWERS IS WRITTEN DOWN, because the gate cannot ask it
# (#825). `lint:pg-upgrade-path` has to tell a burned dead end from a
# stranded installation, and a filename cannot: a version that is only
# ever an upgrade TARGET either burned or published fine and simply was
# not derived from. That is a fact about release assets, which is the
# question this script is already asking to pick a predecessor — so it
# answers it for EVERY version in the graph, once, and commits the
# answer as derived state alongside the upgrade script itself.
#
# One listing, not one per candidate, and one function (#1592):
# previous_release.py's `record` lists every non-draft release's assets
# once, writes the record from that listing, and prints each extension's
# predecessor from the same listing by the same function the mint guard
# and the build's backstop call. The record, this derivation and both
# guards therefore cannot name different predecessors. The listing's jq
# only maps, never aggregates: `--paginate` applies a filter per page,
# and an aggregating one answered once PER MATCHING PAGE (#825).
record=".pgrx-installable"
predecessors=$("${ORG_PYTHON}" "${predecessor_helper[@]}" record --repo "${GITHUB_REPOSITORY}" \
  --version "${VERSION}" --out "${record}" "${controls[@]}")
org_say "installable set recorded in ${record}:"
sed 's/^/  /' "${record}"
files_out=" ${record}"

if grep -qxF "${VERSION}" <<< "${graph_targets}"; then
  org_say "upgrade graph already reaches ${VERSION}; nothing to derive"
  emit "files=${files_out# }"
  exit 0
fi
# The predecessor's candidates are the graph's versions LOWER than this
# one (#1592): on an older line, a newer published version is not where
# an installation upgrades to this release from. On a single line they
# are the whole graph, and `below_head` is the graph's head.
graph_below=$("${ORG_PYTHON}" "${predecessor_helper[@]}" graph --below "${VERSION}" "${controls[@]}")
below_head=$(head -n 1 <<< "${graph_below}")
if [[ -n ${PREV_MANIFEST} && ${PREV_MANIFEST} != "${below_head}" ]]; then
  org_say "NOTE: manifest carried ${PREV_MANIFEST} but the upgrade graph reaches ${below_head}"
fi

# rust and cargo-pgrx are caller build inputs, pinned in the caller's own
# mise config, read by the canon's one reader of a caller's pins (#1333):
# under whichever backend key pins them, and for a LIST of rust versions
# (a repo that fuzzes declares a nightly beside the stable one, .github#445)
# the first entry, the one mise puts on PATH and this build must use.
pins=$("${ORG_PYTHON}" -I "${canon}/belt" caller-pins env --input-of "the pgrx-extension class" \
  RUST_VERSION=rust PGRX_VERSION=cargo-pgrx) || {
  org_finding "" "rust and cargo:cargo-pgrx must be pinned in this repository's mise config"
  exit 1
}
RUST_VERSION=$(sed -n 's/^RUST_VERSION=//p' <<< "${pins}")
PGRX_VERSION=$(sed -n 's/^PGRX_VERSION=//p' <<< "${pins}")
export RUST_VERSION PGRX_VERSION

# One canonical cell derives the script: the newest PG major that both the
# base-image mapping carries and the previous release shipped, on the
# runner's own architecture. The script is pure SQL — identical across
# cells — and every cell still executes it at publish.
mapping=$(python3 -c '
import json, tomllib
with open("'"${canon}"'/docker/pgrx-base-images.toml", "rb") as f:
    t = tomllib.load(f)
print(json.dumps(t))
')

for control in "${controls[@]}"; do
  crate_dir=$(dirname "${control}")
  name=$(basename "${control}" .control)

  # Find the release that CARRIES the previous tarballs, rather than
  # assuming its tag (#762). For a repository that has always released
  # under the canon this is `v<prev>` and the search finds exactly that;
  # for an imported one the same bytes sit on whatever tag its old scheme
  # used — edtf's 1.2.3 extension tarballs are on `edtf-postgres-v1.2.3`,
  # and `v1.2.3` exists as a tag with no release object and therefore no
  # assets at all. Asking which release has the file is true in both
  # cases; asking which tag ought to have it is true in one.
  #
  # Only installations that can exist need a path: same carve-out as the
  # publish guard. A repo adding the class mid-life has a previous
  # release and no previous extension.
  # The predecessor walks the graph newest-first and stops at the first
  # version a non-draft release actually CARRIES (#816). A graph version
  # no release carries is not installable — burned, or its release
  # deleted — so it cannot be the predecessor; skipping it is not the
  # same as concluding there is no predecessor. Only when NO version in
  # the whole graph is carried has this extension truly never shipped.
  #
  # The predecessor is previous_release.py's answer, printed above by
  # `record` from the same listing the record was written from (#1592).
  # The candidates it passed over are named here, newest first.
  answer=$(awk -F'\t' -v ext="${name}" '$1 == ext { print $2 "\t" $3; exit }' \
    <<< "${predecessors}")
  prev="${answer%%$'\t'*}"
  prev_tag="${answer#*$'\t'}"
  while IFS= read -r candidate; do
    [[ -n ${candidate} ]] || continue
    [[ ${candidate} != "${prev}" ]] || break
    org_say "NOTE: ${name} ${candidate} is in the upgrade graph but no non-draft release"
    echo "      carries its tarballs; not installable, trying the next older version"
  done <<< "${graph_below}"
  if [[ -z ${prev} ]]; then
    org_say "no non-draft release carries any ${name} tarball; first publish of this extension, no upgrade path needed"
    continue
  fi
  if [[ ${prev} != "${below_head}" ]]; then
    org_say "NOTE: deriving ${name} from ${prev}, the newest installable published"
    org_say "      version; graph head ${below_head} is not installable"
  fi
  shipped=$(gh release view "${prev_tag}" --repo "${GITHUB_REPOSITORY}" \
    --json assets --jq \
    "[.assets[].name | select(startswith(\"${name}-${prev}-pg\"))]")

  pg=""
  for candidate_pg in $(jq -r '.build | keys | sort_by(tonumber) | reverse | .[]' <<< "${mapping}"); do
    if jq -e --arg a "${name}-${prev}-pg${candidate_pg}-linux-amd64.tar.gz" \
      'index($a)' <<< "${shipped}" > /dev/null; then
      pg="${candidate_pg}"
      break
    fi
  done
  if [[ -z ${pg} ]]; then
    org_finding "" "${prev_tag} shipped ${name} tarballs, but none for a PG major the base-image mapping carries"
    exit 1
  fi
  build_image=$(jq -r --arg pg "${pg}" '.build[$pg]' <<< "${mapping}")

  work=$(mktemp -d)
  # mktemp -d is 0700 owned by the runner, and this directory is mounted
  # into the containers as /work. Both inner scripts drop to `postgres`
  # (pgrx refuses to run as root), and that user cannot traverse 0700 —
  # bash then reports "Permission denied" for a file it can otherwise
  # read, and the step dies with a bare exit 126. Chowning inside the
  # container is not an option for the proof pass, which mounts /work
  # read-only, so the traversal bit is set here, once, on the host.
  chmod 755 "${work}"
  mkdir -p "${work}/prevroot" "${work}/out"
  # The writers of findings and workflow commands, and the tracked-file
  # producer the findings writer sources (#1986), where both containers
  # read /work.
  cp "${canon}/mise/findings.sh" "${canon}/mise/workflow-command.sh" \
    "${canon}/mise/tracked.sh" "${work}/"

  echo "deriving ${name}: ${prev} -> ${VERSION} (pg${pg})"
  gh release download "${prev_tag}" --repo "${GITHUB_REPOSITORY}" \
    --pattern "${name}-${prev}-pg${pg}-linux-amd64.tar.gz" \
    --output "${work}/prev.tar.gz"
  tar -xzf "${work}/prev.tar.gz" -C "${work}/prevroot"

  # WHERE THE PREVIOUS TREE IS, resolved once and read by everything that
  # needs it (#780). Our own tarballs are packed from a staging directory
  # and carry a `pkgroot/` top level; an imported repository's were packed
  # from `/` and carry `./usr/...` directly. The payload and every path
  # below that level are identical — the difference is one archive
  # component, not a difference in the extension.
  #
  # This used to be two answers that could disagree, and did: the schema
  # was located with a recursive `find` (layout-agnostic, so it passed on
  # edtf) while the proof mounted a hard-coded `prevroot/pkgroot` (which
  # did not exist there). The mismatch therefore surfaced as `cp: cannot
  # stat` AFTER a full candidate compile, two minutes past the point it
  # was knowable. One variable now, asserted here.
  prev_root="${work}/prevroot/pkgroot"
  [[ -d ${prev_root} ]] || prev_root="${work}/prevroot"
  if [[ ! -d ${prev_root}/usr/lib/postgresql/${pg}/lib ]]; then
    org_finding "" "${prev_tag} tarball has no usr/lib/postgresql/${pg}/lib under its package root" \
      "looked in ${prev_root#"${work}/"} (of $(basename "${work}/prev.tar.gz"))" \
      "the archive is neither pkgroot/usr/... nor ./usr/..., which is the shape a" \
      "pgrx package tarball has; nothing downstream can read it"
    exit 1
  fi

  # Same root, so the two cannot disagree again. -print -quit, never
  # `| head -1`: find's own first-match stop, so there is no pipe to break
  # and no walk to finish (#682).
  prev_schema=$(find "${prev_root}" -type f -name "${name}--${prev}.sql" -print -quit)
  if [[ -z ${prev_schema} ]]; then
    org_finding "" "${prev_tag} tarball carries no generated schema ${name}--${prev}.sql"
    exit 1
  fi

  # Build the candidate package inside the digest-pinned consumer
  # Postgres — same container, same pins, same layout as the build leg of
  # build-pgrx-extension.yml, minus the test suite (CI gates tests; this
  # leg needs only the generated schema and the loadable library).
  cat > "${work}/build.sh" << 'EOSH'
set -euo pipefail
. /work/findings.sh
: "${MISE_TASK_NAME:=generate-pgrx-upgrade.sh}"
export DEBIAN_FRONTEND=noninteractive
apt-get update -qq
# Headers at exactly the server the pinned image already carries
# (#1157): unversioned, apt serves the newest minor, and the library
# links against symbols the image's server does not have. Textually
# identical to the install in release/pgrx/build-root.sh, asserted by
# tests/release/test_generate_pgrx_upgrade.py: the two containers mount
# different trees, so they cannot share one script.
server=$(dpkg-query -W -f="\${Version}" "postgresql-${PG}")
if ! apt-cache show "postgresql-server-dev-${PG}=${server}" > /dev/null 2>&1; then
  msg="image ${BUILD_IMAGE} carries server ${server}; the apt repository"
  msg+=" no longer serves its headers — move the image pin in"
  msg+=" docker/pgrx-base-images.toml"
  org_finding_annotated "" "${msg}"
  exit 1
fi
apt-get install -y -qq --no-install-recommends \
  "postgresql-server-dev-${PG}=${server}" build-essential \
  ca-certificates curl pkg-config clang llvm libclang-dev git
after=$(dpkg-query -W -f="\${Version}" "postgresql-${PG}")
[[ ${after} == "${server}" ]] || {
  org_finding_annotated "" "the build moved the server from ${server} to ${after}"
  exit 1
}
mkdir -p /build
cp -a /src/. /build/
chown -R postgres:postgres /build /work/out \
  "$(/usr/bin/pg_config --pkglibdir)" \
  "$(/usr/bin/pg_config --sharedir)/extension"
exec su -w PG,CRATE_DIR,RUST_VERSION,PGRX_VERSION \
  postgres -s /bin/bash /work/build-inner.sh
EOSH
  cat > "${work}/build-inner.sh" << 'EOSH'
set -euo pipefail
export HOME=/var/lib/postgresql
curl --proto "=https" --tlsv1.2 -sSf -o /tmp/rustup-init \
  "https://static.rust-lang.org/rustup/dist/$(uname -m)-unknown-linux-gnu/rustup-init"
chmod +x /tmp/rustup-init
/tmp/rustup-init -y --profile minimal \
  --default-toolchain "${RUST_VERSION}" --no-modify-path
. "${HOME}/.cargo/env"
cargo install cargo-pgrx --version "${PGRX_VERSION}" --locked
cargo pgrx init "--pg${PG}" /usr/bin/pg_config
cd "/build/${CRATE_DIR}"
export CARGO_INCREMENTAL=0
cargo pgrx package \
  --no-default-features --features "pg${PG}" \
  --pg-config /usr/bin/pg_config \
  --out-dir /work/out/pkgroot
EOSH
  docker run --rm \
    --env PG="${pg}" --env CRATE_DIR="${crate_dir}" \
    --env BUILD_IMAGE="${build_image}" \
    --env RUST_VERSION --env PGRX_VERSION \
    --volume "${PWD}:/src:ro" \
    --volume "${work}:/work" \
    "${build_image}" \
    bash /work/build.sh

  # -print -quit, never `| head -1`: find's own first-match stop, so
  # there is no pipe to break and no walk to finish (#682).
  new_schema=$(find "${work}/out/pkgroot" -type f -name "${name}--${VERSION}.sql" -print -quit)
  if [[ -z ${new_schema} ]]; then
    org_finding "" "candidate build produced no generated schema ${name}--${VERSION}.sql"
    exit 1
  fi

  data_fragment=""
  if [[ -f "${crate_dir}/sql/next-data.sql" ]]; then
    data_fragment="${crate_dir}/sql/next-data.sql"
  fi

  # Derive. The generator understands pgrx's own regular, deterministic
  # output — not arbitrary SQL — and fails loudly on anything it cannot
  # soundly migrate, naming the statement. The round-trip proof below is
  # the authority either way.
  EXT_NAME="${name}" PREV_V="${prev}" NEW_V="${VERSION}" \
    MISE_TASK_NAME="${MISE_TASK_NAME}" \
    "${ORG_PYTHON}" -I "${canon}/belt" upgrade-script \
    "${prev_schema}" "${new_schema}" "${work}/upgrade.sql" \
    ${data_fragment:+"${data_fragment}"}

  # Prove it: the exact consumer sequence, then catalog equality. pg_dump
  # cannot see extension members, so equality is read from pg_depend with
  # per-kind definitions. prokind, typtype and typcategory are "char",
  # which has no || of its own: uncast, the query dies at parse time
  # (#1324), so each is cast to text, and typlen with them.
  cat > "${work}/snapshot.sql" << 'EOSQL'
SELECT pg_identify_object(d.classid, d.objid, 0)::text
       || ' | ' ||
       CASE
         WHEN d.classid = 'pg_proc'::regclass AND p.prokind = 'f'
           THEN pg_get_functiondef(d.objid)
         WHEN d.classid = 'pg_proc'::regclass
           THEN p.prokind::text || ':' || pg_get_function_identity_arguments(d.objid)
         WHEN d.classid = 'pg_type'::regclass
           THEN t.typtype::text || ':' || t.typlen::text || ':' || t.typcategory::text
                || ':' || t.typinput::text || ':' || t.typoutput::text
         ELSE ''
       END
FROM pg_depend d
LEFT JOIN pg_proc p ON d.classid = 'pg_proc'::regclass AND p.oid = d.objid
LEFT JOIN pg_type t ON d.classid = 'pg_type'::regclass AND t.oid = d.objid
WHERE d.refclassid = 'pg_extension'::regclass
  AND d.refobjid = (SELECT oid FROM pg_extension WHERE extname = :'ext')
  AND d.deptype = 'e'
ORDER BY 1
EOSQL
  cat > "${work}/proof.sh" << 'EOSH'
set -euo pipefail
lib="/usr/lib/postgresql/${PG}/lib"
ext="/usr/share/postgresql/${PG}/extension"
cp -a "/prev${lib}/." "${lib}/"
cp -a "/prev${ext}/." "${ext}/"
su -w PG,NAME,PREV postgres -s /bin/bash -c '
  set -euo pipefail
  bin="/usr/lib/postgresql/${PG}/bin"
  "${bin}/initdb" -D /tmp/pgdata -A trust > /dev/null
  "${bin}/pg_ctl" -D /tmp/pgdata -o "-c listen_addresses=" -w start > /dev/null
  createdb upgraded
  psql -v ON_ERROR_STOP=1 -d upgraded -c "CREATE EXTENSION ${NAME} VERSION '\''${PREV}'\'';" > /dev/null
'
# The candidate package lands over the old — exactly what a package
# upgrade does — together with the derived script under proof.
cp -a "/new${lib}/." "${lib}/"
cp -a "/new${ext}/." "${ext}/"
cp /work/upgrade.sql "${ext}/${NAME}--${PREV}--${NEW}.sql"
su -w PG,NAME,PREV,NEW postgres -s /bin/bash -c '
  set -euo pipefail
  . /work/findings.sh
  : "${MISE_TASK_NAME:=generate-pgrx-upgrade.sh}"
  psql -v ON_ERROR_STOP=1 -d upgraded -c "ALTER EXTENSION ${NAME} UPDATE TO '\''${NEW}'\'';" > /dev/null
  got=$(psql -v ON_ERROR_STOP=1 -d upgraded -tA -c \
    "SELECT extversion FROM pg_extension WHERE extname = '\''${NAME}'\'';")
  if [[ ${got} != "${NEW}" ]]; then
    org_finding_annotated "" "upgrade left extversion ${got}, wanted ${NEW}"
    exit 1
  fi
  createdb fresh
  psql -v ON_ERROR_STOP=1 -d fresh -c "CREATE EXTENSION ${NAME} VERSION '\''${NEW}'\'';" > /dev/null
  # ON_ERROR_STOP: without it psql exits 0 on an SQL error, the snapshot
  # is empty, and two empty files compare equal (#1324). An extension has
  # at least one member object, so an empty snapshot read nothing.
  for db in upgraded fresh; do
    psql -v ON_ERROR_STOP=1 -d "${db}" -tA -v ext="${NAME}" -f /work/snapshot.sql > "/tmp/${db}.snap"
    if [[ ! -s /tmp/${db}.snap ]]; then
      org_finding_annotated "" "${db} catalog snapshot of ${NAME} is empty — the proof read nothing"
      exit 1
    fi
  done
  if ! diff -u /tmp/upgraded.snap /tmp/fresh.snap; then
    emsg="upgraded ${NAME} catalog differs from a fresh ${NEW} install — the derived script is"
    emsg+=" unsound; see the diff above"
    org_finding_annotated "" "${emsg}"
    exit 1
  fi
  # Rows, not lines: a function definition spans several lines.
  objects=$(psql -v ON_ERROR_STOP=1 -d fresh -tA -v ext="${NAME}" \
    <<< "SELECT count(*) FROM ($(< /work/snapshot.sql)) AS snapshot;")
  echo "proof: ${NAME} ${PREV} -> ${NEW} upgraded catalog identical to fresh install (${objects} objects)"
'
EOSH
  docker run --rm \
    --env PG="${pg}" --env NAME="${name}" \
    --env PREV="${prev}" --env NEW="${VERSION}" \
    --volume "${prev_root}:/prev:ro" \
    --volume "${work}/out/pkgroot:/new:ro" \
    --volume "${work}:/work:ro" \
    "${build_image}" \
    bash /work/proof.sh

  mkdir -p "${crate_dir}/sql"
  cp "${work}/upgrade.sql" "${crate_dir}/sql/${name}--${prev}--${VERSION}.sql"
  files_out="${files_out} ${crate_dir}/sql/${name}--${prev}--${VERSION}.sql"
  org_say "upgrade path derived and proven: ${crate_dir}/sql/${name}--${prev}--${VERSION}.sql"

  # The data fragment is consumed by this cycle: it leaves the tree in the
  # same release commit that ships its content inside the derived script.
  if [[ -n ${data_fragment} ]]; then
    rm "${data_fragment}"
    files_out="${files_out} ${data_fragment}"
  fi

  # The build container chowns /work/out to postgres, so its files — and
  # the directories holding them — come back owned by a container uid the
  # runner cannot write to, and a plain rm -rf dies with Permission denied
  # AFTER the upgrade script has already been derived, proven and copied.
  # Hand ownership back from inside the same image (already pulled, so no
  # extra network) rather than reaching for sudo, which this script should
  # not need and would not have outside a runner.
  # shellcheck disable=SC2312  # id(1) on the local uid cannot meaningfully fail
  docker run --rm --volume "${work}:/work" "${build_image}" \
    chown -R "$(id -u):$(id -g)" /work
  rm -rf "${work}"
done

emit "files=${files_out# }"
